    q: 'A US private equity firm signs a one-way NDA with a publicly traded UK target. The NDA contains a use clause permitting use "solely to evaluate a possible negotiated transaction with Discloser" and a 12-month standstill. Six months in, the PE firm believes it could win a hostile tender. Which statement is most accurate?',
