    q: 'In February 2026, a US-headquartered tech company is acquiring a Delaware-incorporated AI start-up for US$200 million. The buyer has US$500 million in annual sales; the target has US$30 million in annual sales. Is HSR notification required under the 2026 thresholds (effective 17 February 2026)?',
