(function() {
  var letterItems = [];
  Object.keys(window).filter(function(k) { return k.indexOf('__QUIZ_') === 0 && !/^__QUIZ_M\d/.test(k); }).forEach(function(k) {
    if (Array.isArray(window[k])) letterItems = letterItems.concat(window[k]);
  });
  var moduleOverrides = {};
  Object.keys(window).filter(function(k) { return /^__QUIZ_M(\d{2})/.test(k); }).forEach(function(k) {
    var m = k.match(/^__QUIZ_M(\d{2})/);
    if (m && Array.isArray(window[k])) moduleOverrides[m[1]] = window[k];
  });
  letterItems = letterItems.filter(function(c) { return !moduleOverrides[c.module]; });
  window.QUIZ = letterItems;
  Object.keys(moduleOverrides).forEach(function(mod) {
    window.QUIZ = window.QUIZ.concat(moduleOverrides[mod]);
  });
})();
